// Compara cada consulta ANTES (sin señalador) y DESPUÉS (con señalador).
// Claude devuelve en "usage" la factura de cada llamada:
//   input_tokens                = tokens a precio completo
//   cache_creation_input_tokens = tokens que se GUARDARON en el escritorio (un poco más caros)
//   cache_read_input_tokens     = tokens LEÍDOS del escritorio (10 veces más baratos)
// Precios de Claude Sonnet 5 por millón de tokens (verificados el 28/09/2026):
// entrada 2 · guardar en el escritorio 2,50 · leer del escritorio 0,20 · salida 10
const pedidos = $('Las consultas, dos veces').all();
const respuestas = $input.all();
const n = pedidos.length / 2;
const mil = x => x.toLocaleString('es-AR');

const costo = u => ((u.input_tokens || 0) * 2 + (u.cache_creation_input_tokens || 0) * 2.5
  + (u.cache_read_input_tokens || 0) * 0.2 + (u.output_tokens || 0) * 10) / 1e6;

let totalAntes = 0, totalDespues = 0;
const filas = [];
for (let i = 0; i < n; i++) {
  const a = respuestas[i].json.usage || {};
  const d = respuestas[i + n].json.usage || {};
  totalAntes += costo(a);
  totalDespues += costo(d);

  let despues = mil(d.input_tokens || 0) + ' a precio completo';
  if (d.cache_creation_input_tokens) despues += ' + ' + mil(d.cache_creation_input_tokens) + ' GUARDADOS en el escritorio (un poco más caros)';
  if (d.cache_read_input_tokens) despues += ' + ' + mil(d.cache_read_input_tokens) + ' LEÍDOS del escritorio (10 veces más baratos)';

  filas.push({ json: {
    consulta: pedidos[i].json.quien,
    antes: mil(a.input_tokens || 0) + ' a precio completo',
    despues,
    costo_antes_usd: Number(costo(a).toFixed(5)),
    costo_despues_usd: Number(costo(d).toFixed(5))
  } });
}

// El ticket de 100: de cada 100 que costaba antes, cuánto cuesta después.
const deCada100 = Math.round(totalDespues / totalAntes * 100);
// Con 600 consultas: el manual se guarda una vez y las otras 599 lo leen del escritorio.
const primera = costo(respuestas[n].json.usage || {});
const siguiente = (totalDespues - primera) / (n - 1);
const con600 = Math.round((primera + siguiente * 599) / (totalAntes / n * 600) * 100);

filas.push({ json: {
  consulta: 'TOTAL (' + n + ' consultas)',
  antes: 'US$ ' + totalAntes.toFixed(4).replace('.', ','),
  despues: 'US$ ' + totalDespues.toFixed(4).replace('.', ','),
  en_palabras: 'Con ' + n + ' consultas, de cada 100 que pagabas antes, ahora pagás ' + deCada100 + '. ' +
    'Con 600 consultas pagarías unos ' + con600 + ': el cupón caché del ticket de 100.'
} });
return filas;
